import './share.scss';
import Image from '../../assets/img.png';
import Map from '../../assets/map.png';
import Friend from '../../assets/friend.png';
import { useContext, useState } from 'react';
import { AuthContext } from '../../context/authContext';
import axios from 'axios';

const Share = () => {
  const { currentUser } = useContext(AuthContext);
  const [desc, setDesc] = useState('');
  const [file, setFile] = useState(null);
  const [preview, setPreview] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    setFile(selectedFile);
    if (selectedFile) {
      const reader = new FileReader();
      reader.onload = () => setPreview(reader.result);
      reader.readAsDataURL(selectedFile);
    } else {
      setPreview(null);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!desc && !file) {
      setError('Please add a description or image to share.');
      return;
    }

    setLoading(true);
    setError(null);

    const formData = new FormData();
    formData.append('desc', desc);
    formData.append('userId', currentUser.id);
    formData.append('name', currentUser.name);
    formData.append('profilePic', currentUser.profilePic);
    if (file) formData.append('img', file);

    try {
      await axios.post('http://localhost:5000/api/posts', formData, {
        headers: {
          Authorization: `Bearer ${localStorage.getItem('token')}`,
          'Content-Type': 'multipart/form-data',
        },
      });
      setDesc('');
      setFile(null);
      setPreview(null);
      window.location.reload(); // Consider updating state instead for SPA experience
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to create post');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="share">
      <div className="container">
        <div className="top">
          <img
            src={currentUser.profilePic || '/default-avatar.png'}
            alt={currentUser.name}
            className="avatar"
          />
          <textarea
            placeholder={`What's on your mind, ${currentUser.name}?`}
            value={desc}
            onChange={(e) => setDesc(e.target.value)}
            rows="3"
            disabled={loading}
          />
        </div>
        {preview && (
          <div className="preview">
            <img src={preview} alt="Preview" className="preview-img" />
            <button
              className="remove-btn"
              onClick={() => {
                setFile(null);
                setPreview(null);
              }}
              title="Remove image"
            >
              ×
            </button>
          </div>
        )}
        <hr />
        <div className="bottom">
          <div className="left">
            <input
              type="file"
              id="file"
              accept="image/*"
              style={{ display: 'none' }}
              onChange={handleFileChange}
              disabled={loading}
            />
            <label htmlFor="file">
              <div className="item">
                <img src={Image} alt="Add Image" />
                <span>Add Image</span>
              </div>
            </label>
            <div className="item disabled">
              <img src={Map} alt="Add Place" />
              <span>Add Place</span>
            </div>
            <div className="item disabled">
              <img src={Friend} alt="Tag Friends" />
              <span>Tag Friends</span>
            </div>
          </div>
          <div className="right">
            <button onClick={handleSubmit} disabled={loading || (!desc && !file)}>
              {loading ? 'Sharing...' : 'Share'}
            </button>
          </div>
        </div>
        {error && <p className="error">{error}</p>}
      </div>
    </div>
  );
};

export default Share;
